require("./trip-data.js");const TripPlanner=require("./frontend/js-modules/trip-planner.js");let passed=0,failed=0;function assert(e,t){e?(passed+=1,console.log(`  ✓ ${t}`)):(failed+=1,console.error(`  ✗ ${t}`))}function section(e,t){console.log(`\n${e}`),t()}section("haversineDistanceKm",()=>{assert(0===TripPlanner.haversineDistanceKm(28.6139,77.209,28.6139,77.209),"distance between identical points is 0");const e=TripPlanner.haversineDistanceKm(28.6139,77.209,27.1767,78.0081);assert(e>150&&e<250,`Delhi–Agra distance is realistic (~200km), got ${e.toFixed(0)}`)}),section("estimateTravelLeg",()=>{const e=TripPlanner.estimateTravelLeg(200,"mid");assert(e.cost>0,"travel leg has a positive cost"),assert(0===e.travelDays,"a 200km hop does not consume a dedicated travel day");assert(1===TripPlanner.estimateTravelLeg(1200,"mid").travelDays,"a 1200km hop consumes a dedicated travel day")}),section("chooseCostTier",()=>{assert("budget"===TripPlanner.chooseCostTier(2e3,10),"low per-day budget -> budget tier"),assert("mid"===TripPlanner.chooseCostTier(35e3,10),"moderate per-day budget -> mid tier"),assert("luxury"===TripPlanner.chooseCostTier(1e5,10),"high per-day budget -> luxury tier")}),section("scoreDestination",()=>{const e={categories:["mountains","adventure"],popularity:5};assert(TripPlanner.scoreDestination(e,["mountains"])>TripPlanner.scoreDestination(e,["beaches"]),"a category match scores higher than a non-match");assert(TripPlanner.scoreDestination(e,[])>0,"an empty preference list still yields a positive baseline score")}),section("generateItinerary — basic generation",()=>{const e=TripPlanner.generateItinerary({budget:5e4,days:7,travelers:1,categories:["mountains"]});assert(e.destinations.length>0,"produces at least one destination"),assert(e.daysUsed<=7,`does not exceed the requested day count (used ${e.daysUsed})`),assert(e.destinations.every(e=>e.categories.includes("mountains")),"every chosen destination matches the requested category"),assert(e.budget.grandTotal>0,"produces a positive total cost estimate")}),section("generateItinerary — budget respected",()=>{assert(TripPlanner.generateItinerary({budget:15e3,days:10,travelers:1,categories:[]}).budget.grandTotal<=17250,"total cost stays close to the requested budget (small tolerance for the forced-minimum destination)")}),section("generateItinerary — falls back gracefully with no category matches",()=>{const e=TripPlanner.generateItinerary({budget:4e4,days:5,travelers:1,categories:["nonexistent-category"]});assert(!0===e.usedFallback,"flags that it had to fall back to the full destination pool"),assert(e.destinations.length>0,"still returns a usable itinerary")}),section("generateItinerary — multi-traveler scales cost",()=>{const e=TripPlanner.generateItinerary({budget:1e5,days:5,travelers:1,categories:["beaches"]});assert(TripPlanner.generateItinerary({budget:1e5,days:5,travelers:4,categories:["beaches"]}).budget.grandTotal>e.budget.grandTotal,"a 4-traveler trip costs more in total than a solo trip with the same itinerary shape")}),section("regenerateItinerary — produces a different anchor when possible",()=>{const e=TripPlanner.generateItinerary({budget:6e4,days:7,travelers:1,categories:["historical"]});assert(TripPlanner.regenerateItinerary(e).destinations[0].id!==e.destinations[0].id,"regenerating swaps out the original anchor destination")}),section("removeDestinationFromItinerary — redistributes freed days",()=>{const e=TripPlanner.generateItinerary({budget:8e4,days:10,travelers:1,categories:["historical","heritage"]});if(e.destinations.length<2)console.log("  (skipped — itinerary only had one destination)");else{const t=e.destinations.reduce((e,t)=>e+t.assignedDays,0),a=TripPlanner.removeDestinationFromItinerary(e,e.destinations[e.destinations.length-1].id),s=a.destinations.reduce((e,t)=>e+t.assignedDays,0);assert(a.destinations.length===e.destinations.length-1,"removes exactly one destination"),assert(s<=t,"redistributed days never exceed the original total")}}),section("buildDailySchedule",()=>{const e=TripPlanner.generateItinerary({budget:5e4,days:6,travelers:1,categories:["spiritual"]}),t=TripPlanner.buildDailySchedule(e);assert(t.length>0,"produces a non-empty day-by-day schedule"),assert(1===t[0].day,"schedule starts at day 1");const a=t.map(e=>e.day);assert(a.every((e,t)=>0===t||e===a[t-1]+1),"day numbers are sequential with no gaps or repeats")}),console.log(`\n${passed} passed, ${failed} failed`),process.exit(failed>0?1:0);